using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class LabVerify {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_LabIdentity/";static string O=>R+"/Docs/Review/2026-11-09_B4_LabIdentity/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var plan=JObject.Parse(File.ReadAllText(H+"changes.json"));var by=ts.ToDictionary(t=>GlobalObjectId.GetGlobalObjectIdSlow(t).ToString());var failures=new List<string>();
 foreach(var p in plan["replacements"]){var t=by[(string)p["id"]];var mf=t.GetComponent<MeshFilter>();if(!AssetDatabase.GetAssetPath(mf.sharedMesh).EndsWith((string)p["model"]+".fbx"))failures.Add(t.name+" wrong mesh");var rr=t.GetComponent<MeshRenderer>();if(rr.sharedMaterials.Length!=mf.sharedMesh.subMeshCount||rr.sharedMaterials.Any(m=>!m))failures.Add(t.name+" materials");if((bool)p["collision"]){var mc=t.GetComponent<MeshCollider>();if(!mc||!mc.enabled||!mc.sharedMesh||mc.convex)failures.Add(t.name+" collision");if(t.GetComponents<Collider>().Count(c=>c.enabled)!=1)failures.Add(t.name+" duplicate collision");}}
 foreach(var id in plan["disable"])if(by[(string)id].gameObject.activeSelf)failures.Add(by[(string)id].name+" still active");
 var before=JArray.Parse(File.ReadAllText(H+"state_before.json"));var changed=new HashSet<string>(plan["replacements"].Select(p=>(string)p["id"]));var disabled=new HashSet<string>(plan["disable"].Select(p=>(string)p));var stateDiff=new List<string>();
 foreach(var old in before){string id=(string)old["id"];if(!by.TryGetValue(id,out var t)){stateDiff.Add("Missing "+old["name"]);continue;}bool eq(JToken a,float[] b)=>a.Values<float>().Zip(b,(x,y)=>Mathf.Abs(x-y)<.0001f).All(x=>x);if(!eq(old["p"],V(t.position))||!eq(old["e"],V(t.eulerAngles))||!eq(old["scale"],V(t.localScale)))stateDiff.Add(t.name+" transform");if((bool)old["active"]!=t.gameObject.activeSelf&&!disabled.Contains(id))stateDiff.Add(t.name+" active");if((string)old["name"]!=t.name&&!changed.Contains(id))stateDiff.Add(t.name+" name");var lights=t.GetComponents<Light>();var ol=old["lights"].ToArray();if(lights.Length!=ol.Length)stateDiff.Add(t.name+" light count");for(int i=0;i<lights.Length;i++){var l=lights[i];var j=ol[i];if(Mathf.Abs(l.intensity-(float)j["intensity"])>1e-5f||Mathf.Abs(l.range-(float)j["range"])>1e-5f||Mathf.Abs(l.spotAngle-(float)j["spotAngle"])>1e-5f||l.enabled!=(bool)j["enabled"]||!eq(j["c"],new[]{l.color.r,l.color.g,l.color.b}))stateDiff.Add(t.name+" light settings");}}
 var player=ts.First(t=>t.parent==null&&t.name.StartsWith("Player"));var meshes=ts.Where(t=>t.gameObject.activeInHierarchy&&t.GetComponent<MeshFilter>()).Select(t=>t.GetComponent<MeshFilter>()).ToArray();int missingMesh=meshes.Count(m=>!m.sharedMesh),missingMaterials=ts.Where(t=>t.gameObject.activeInHierarchy).SelectMany(t=>t.GetComponents<Renderer>()).Sum(r=>r.sharedMaterials.Count(m=>!m));var result=new{failures,stateDiff,transforms=ts.Length,beforeTransforms=before.Count,lights=ts.Sum(t=>t.GetComponents<Light>().Length),missingMesh,missingMaterials,playerPosition=V(player.position),playerEuler=V(player.eulerAngles),playing=Application.isPlaying,dirty=s.isDirty};File.WriteAllText(O+"verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object Finish(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var t=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Single(t=>t.name=="B4_E03_ElectrodePrepBench_02");Selection.activeGameObject=t.gameObject;var view=SceneView.lastActiveSceneView;if(view){view.pivot=t.TransformPoint(new Vector3(0,1.05f,0));view.rotation=Quaternion.LookRotation(t.TransformDirection(new Vector3(0,-.5f,-1)),Vector3.up);view.size=1.6f;view.Repaint();}return new{selected=t.name,scene=s.path,saved=!s.isDirty};}
}
